    // Derives the `packages` map key for a given `snapshots` map key. The two
    // differ when the snapshot key carries a peer suffix (e.g.
    // `foo@1.0.0(bar@1.0.0)`), which the packages key omits.
    fn package_key_from_snapshot_key(&self, key: &str) -> Result<String, crate::Error> {
        let dp = DepPath::parse(self.version(), key).map_err(Error::from)?;
        Ok(self.format_key(dp.name, dp.version))
    }

    // Adds an injected `file:` workspace package (identified by its snapshot
    // `key`) to the pruned lockfile, populating both the `packages` and
    // `snapshots` maps, and traversing the injected package's direct
    // dependencies to add their entries as well.
    fn add_injected_package(
        &self,
        key: &str,
        pruned_packages: &mut Packages,
        pruned_snapshots: &mut Option<Snapshots>,
    ) -> Result<(), crate::Error> {
        // Add the `packages` entry for the injected package itself.
        let package_key = self.package_key_from_snapshot_key(key)?;
        if let Some(entry) = self.get_packages(&package_key) {
            pruned_packages
                .entry(package_key)
                .or_insert_with(|| entry.clone());
        }

        // Injected packages (and their transitive deps) only have `snapshots`
        // entries in v7/v9 lockfiles.
        let Some(snapshots) = self.snapshots.as_ref() else {
            return Ok(());
        };
        let Some(snapshot) = snapshots.get(key) else {
            return Ok(());
        };

        if let Some(pruned_snapshots) = pruned_snapshots.as_mut() {
            pruned_snapshots
                .entry(key.to_string())
                .or_insert_with(|| snapshot.clone());
        }

        // Traverse the direct dependencies of the injected package, adding both
        // the `snapshots` and `packages` entry for each.
        for (dep_name, dep_version) in snapshot.dependencies() {
            let dep_key = self.format_key(&dep_name, &dep_version);

            if let Some(pruned_snapshots) = pruned_snapshots.as_mut() {
                if let Some(dep_snapshot) = snapshots.get(&dep_key) {
                    pruned_snapshots
                        .entry(dep_key.clone())
                        .or_insert_with(|| dep_snapshot.clone());
                }
            }

            let dep_package_key = self.package_key_from_snapshot_key(&dep_key)?;
            if let Some(dep_entry) = self.get_packages(&dep_package_key) {
                pruned_packages
                    .entry(dep_package_key)
                    .or_insert_with(|| dep_entry.clone());
            }
        }

        Ok(())
    }
